//! Sealed continuous PR101 verification and an opt-in transactional driver.
//!
//! Target: y' = lambda (y - sin t) + cos t + eta (y - sin t)^2,
//! on 0 <= t <= 1, identity mass. A candidate is generated by RODAS5P,
//! then certified against this immutable target, not an attached exact solution.
use std::sync::Arc;

use rodas5p_core::directed::{Interval, add_up, div_up, exp_interval, mul_up, sub_up};
use rodas5p_core::{CoreError, DenseMatrix, LinearMethod, LinearSolverConfig, WorkCounters};
use serde::Serialize;
use thiserror::Error;

use crate::{
    AdaptiveStepConfig, DenseOutputError, DenseSegmentWork, OdeProblem, Rodas5pQuarticSegment,
    sequential_step,
};

// Provider operations count attempted interval arithmetic/directed primitive
// API calls (including mag); finite point construction and comparisons do not
// count as arithmetic. Every fallible primitive is charged individually.
macro_rules! op {
    ($w:expr, $expr:expr) => {{
        $w.charge_provider_operations(1);
        $expr
    }};
}

#[derive(Debug, Error)]
pub enum Pr101Error {
    #[error(transparent)]
    Core(#[from] CoreError),
    #[error(transparent)]
    Dense(#[from] DenseOutputError),
    #[error("invalid PR101 input: {0}")]
    Invalid(&'static str),
    #[error("continuous PR101 error radius {radius:e} exceeds tube {tube:e}")]
    Tube { radius: f64, tube: f64 },
}

/// Immutable target; arbitrary point callbacks cannot be substituted.
#[derive(Clone, Copy, Debug)]
pub struct Pr101Model {
    lambda: f64,
    eta: f64,
}

/// Diagnostics copied out of a sealed segment; these copies confer no authority.
#[derive(Clone, Copy, Debug, Serialize)]
pub struct Pr101Bound {
    pub residual_upper: f64,
    pub logarithmic_norm_upper: f64,
    pub endpoint_radius: f64,
    pub uniform_radius: f64,
    pub initial_radius: f64,
    pub tube_radius: f64,
}

/// Only verified construction can produce this owner. Its curve and radius are
/// private and cannot be independently edited or deserialized.
#[derive(Clone, Debug)]
pub struct Pr101VerifiedSegment {
    curve: Rodas5pQuarticSegment,
    t0: f64,
    t1: f64,
    bound: Pr101Bound,
}

#[derive(Clone, Copy, Debug, Serialize)]
pub struct Pr101Output {
    time: f64,
    center: f64,
    radius: f64,
}
impl Pr101Output {
    pub fn time(&self) -> f64 {
        self.time
    }
    pub fn center(&self) -> f64 {
        self.center
    }
    pub fn radius(&self) -> f64 {
        self.radius
    }
}

impl Pr101VerifiedSegment {
    pub fn bounds(&self) -> Pr101Bound {
        self.bound
    }
    pub fn span(&self) -> (f64, f64) {
        (self.t0, self.t1)
    }
    /// Includes displacement between the binary64 output and the exact stored
    /// polynomial, in addition to the continuous ODE error.
    pub fn evaluate(
        &self,
        time: f64,
        work: &mut DenseSegmentWork,
    ) -> Result<Pr101Output, Pr101Error> {
        let mut center = [0.0];
        let mut value = [Interval::point(0.0)?];
        self.curve
            .evaluate_center_at_into(time, &mut center, work)?;
        self.curve.evaluate_value_at_into(time, &mut value, work)?;
        let displacement = op!(work, value[0].sub(Interval::point(center[0])?))?;
        let displacement = op!(work, displacement.mag());
        let radius = op!(work, add_up(self.bound.uniform_radius, displacement))?;
        Ok(Pr101Output {
            time,
            center: center[0],
            radius,
        })
    }
}

/// A completed or interrupted run. Partial results contain only committed,
/// verified segments. Costs of rejected attempts remain in both ledgers.
#[derive(Debug)]
pub struct Pr101Run {
    segments: Vec<Pr101VerifiedSegment>,
    outputs: Vec<Pr101Output>,
    pub success: bool,
    pub failure: Option<String>,
    pub attempts: usize,
    pub rejected_attempts: usize,
    pub solver_work: WorkCounters,
    pub verification_work: DenseSegmentWork,
}
impl Pr101Run {
    pub fn outputs(&self) -> &[Pr101Output] {
        &self.outputs
    }
    pub fn segments(&self) -> &[Pr101VerifiedSegment] {
        &self.segments
    }
}

fn power_sum_bound(
    coefficients: &[Interval],
    work: &mut DenseSegmentWork,
) -> Result<f64, Pr101Error> {
    let mut sum = 0.0;
    for coefficient in coefficients {
        let magnitude = op!(work, coefficient.mag());
        sum = op!(work, add_up(sum, magnitude))?;
    }
    Ok(sum)
}

/// Taylor of sin/cos about zero to degree 24, with a Lagrange remainder.
/// All inputs in [0,1]; every derivative has magnitude at most one.
fn trig_at(time: f64, work: &mut DenseSegmentWork) -> Result<(Interval, Interval), Pr101Error> {
    let zero = Interval::point(0.0)?;
    let mut sin = zero;
    let mut cos = zero;
    let mut term = Interval::point(1.0)?;
    for k in 0..=24 {
        match k % 4 {
            0 => cos = op!(work, cos.add(term))?,
            1 => sin = op!(work, sin.add(term))?,
            2 => cos = op!(work, cos.sub(term))?,
            _ => sin = op!(work, sin.sub(term))?,
        }
        term = op!(work, term.scale(time))?;
        term = op!(work, term.div(Interval::point((k + 1) as f64)?))?;
    }
    // term now encloses t^25/25!. No scalar 1/factorial is rounded first.
    let remainder = op!(work, term.mag());
    let remainder = Interval::new(-remainder, remainder)?;
    sin = op!(work, sin.add(remainder))?;
    cos = op!(work, cos.add(remainder))?;
    Ok((sin, cos))
}

/// Local degree-12 trigonometric polynomials in theta, with physical h.
fn trig_polynomials(
    t0: f64,
    h: f64,
    work: &mut DenseSegmentWork,
) -> Result<([Interval; 13], [Interval; 13], f64), Pr101Error> {
    let (s, c) = trig_at(t0, work)?;
    let zero = Interval::point(0.0)?;
    let mut sin = [zero; 13];
    let mut cos = [zero; 13];
    let mut factor = Interval::point(1.0)?;
    for k in 0..=12 {
        let (ds, dc) = match k % 4 {
            0 => (s, c),
            1 => (c, -s),
            2 => (-s, -c),
            _ => (-c, s),
        };
        sin[k] = op!(work, ds.mul(factor))?;
        cos[k] = op!(work, dc.mul(factor))?;
        factor = op!(work, factor.scale(h))?;
        factor = op!(work, factor.div(Interval::point((k + 1) as f64)?))?;
    }
    Ok((sin, cos, op!(work, factor.mag())))
}

fn signed_transport(
    mu: f64,
    h: f64,
    initial: f64,
    residual: f64,
    work: &mut DenseSegmentWork,
) -> Result<f64, Pr101Error> {
    let (gain, integral) = if mu == 0.0 {
        (1.0, h)
    } else {
        let exponent = op!(work, Interval::point(mu)?.scale(h))?;
        let upper = op!(work, exp_interval(exponent.hi))?;
        let gain = upper.hi;
        let integral = if mu < 0.0 {
            let lower = op!(work, exp_interval(exponent.lo))?;
            let numerator = op!(work, sub_up(1.0, lower.lo))?;
            op!(work, div_up(numerator, -mu)).unwrap_or(h).min(h)
        } else {
            let coarse = op!(work, mul_up(h, gain))?;
            let numerator = op!(work, sub_up(gain, 1.0))?;
            op!(work, div_up(numerator, mu))
                .unwrap_or(coarse)
                .min(coarse)
        };
        (gain, integral)
    };
    let transported = op!(work, mul_up(gain, initial))?;
    let defect = op!(work, mul_up(integral, residual))?;
    Ok(op!(work, add_up(transported, defect))?)
}

impl Pr101Model {
    pub fn new(lambda: f64, eta: f64) -> Result<Self, Pr101Error> {
        if !(lambda.is_finite() && eta.is_finite()) {
            return Err(Pr101Error::Invalid("finite coefficients required"));
        }
        Ok(Self { lambda, eta })
    }

    fn candidate_problem(&self) -> Result<OdeProblem, Pr101Error> {
        let (lambda, eta) = (self.lambda, self.eta);
        Ok(OdeProblem::new(
            "sealed-pr101",
            1,
            Arc::new(move |t, y, out| {
                let z = y[0] - t.sin();
                out[0] = lambda * z + t.cos() + eta * z * z;
                Ok(())
            }),
            None,
            Some(Arc::new(move |t, y| {
                DenseMatrix::new(1, 1, vec![lambda + 2.0 * eta * (y[0] - t.sin())])
            })),
            Some(Arc::new(move |t, y, v, out| {
                out[0] = (lambda + 2.0 * eta * (y[0] - t.sin())) * v[0];
                Ok(())
            })),
            Some(Arc::new(move |t, y, out| {
                out[0] = -lambda * t.cos() - t.sin() - 2.0 * eta * (y[0] - t.sin()) * t.cos();
                Ok(())
            })),
            false,
            None,
            None,
        )?)
    }

    /// Certifies an arbitrary candidate polynomial against this target. The
    /// premise is |y(t0)-q(t0)| <= initial_radius. No trust in its generator is
    /// needed, because the complete continuous defect is recomputed here.
    pub fn verify_segment(
        &self,
        curve: Rodas5pQuarticSegment,
        initial_radius: f64,
        tube_radius: f64,
        work: &mut DenseSegmentWork,
    ) -> Result<Pr101VerifiedSegment, Pr101Error> {
        work.validation_operations = work.validation_operations.saturating_add(1);
        if !(initial_radius.is_finite()
            && initial_radius >= 0.0
            && tube_radius.is_finite()
            && tube_radius >= initial_radius)
        {
            return Err(Pr101Error::Invalid(
                "finite tube must contain initial radius",
            ));
        }
        let (t0, t1, h, q) = curve.scalar_span_and_power(work)?;
        if !(0.0 <= t0 && t0 < t1 && t1 <= 1.0) {
            return Err(Pr101Error::Invalid("verified time domain is [0,1]"));
        }
        let (sin, cos, trig_remainder) = trig_polynomials(t0, h, work)?;
        let zero = Interval::point(0.0)?;
        let mut z = [zero; 13];
        for k in 0..13 {
            z[k] = op!(work, q.get(k).copied().unwrap_or(zero).sub(sin[k]))?;
        }
        let z_polynomial_bound = power_sum_bound(&z, work)?;
        let z_bound = op!(work, add_up(z_polynomial_bound, trig_remainder))?;
        let mut defect = [zero; 25];
        for k in 0..25 {
            if k < 4 {
                let derivative = op!(work, q[k + 1].scale((k + 1) as f64))?;
                defect[k] = op!(work, derivative.div(Interval::point(h)?))?;
            }
            if k < 13 {
                defect[k] = op!(work, defect[k].sub(cos[k]))?;
                let linear = op!(work, z[k].scale(self.lambda))?;
                defect[k] = op!(work, defect[k].sub(linear))?;
            }
        }
        // Form the nonlinear coefficient convolution before summing norms.
        for i in 0..13 {
            for j in i..13 {
                let product = op!(work, z[i].mul(z[j]))?;
                let mut product = op!(work, product.scale(self.eta))?;
                // z_i*z_j and z_j*z_i are the same exact scalar product.
                // Visit it once; double only off-diagonal contributions.
                if i != j {
                    product = op!(work, product.scale(2.0))?;
                }
                defect[i + j] = op!(work, defect[i + j].sub(product))?;
            }
        }
        let mut residual = power_sum_bound(&defect, work)?;
        let linear_tail = op!(work, mul_up(self.lambda.abs(), trig_remainder))?;
        residual = op!(work, add_up(residual, linear_tail))?;
        let twice_z = op!(work, mul_up(2.0, z_polynomial_bound))?;
        let nonlinear_factor = op!(work, add_up(twice_z, trig_remainder))?;
        let nonlinear_tail = op!(work, mul_up(nonlinear_factor, trig_remainder))?;
        let nonlinear_tail = op!(work, mul_up(self.eta.abs(), nonlinear_tail))?;
        residual = op!(work, add_up(residual, nonlinear_tail))?;
        residual = op!(work, add_up(residual, trig_remainder))?;
        let tube_z = op!(work, add_up(z_bound, tube_radius))?;
        let nonlinear_mu = op!(work, mul_up(2.0, self.eta.abs()))?;
        let nonlinear_mu = op!(work, mul_up(nonlinear_mu, tube_z))?;
        let mu = op!(work, add_up(self.lambda, nonlinear_mu))?;
        let endpoint = signed_transport(mu, h, initial_radius, residual, work)?;
        let uniform = initial_radius.max(endpoint);
        if uniform > tube_radius {
            return Err(Pr101Error::Tube {
                radius: uniform,
                tube: tube_radius,
            });
        }
        let bound = Pr101Bound {
            residual_upper: residual,
            logarithmic_norm_upper: mu,
            endpoint_radius: endpoint,
            uniform_radius: uniform,
            initial_radius,
            tube_radius,
        };
        Ok(Pr101VerifiedSegment {
            curve,
            t0,
            t1,
            bound,
        })
    }

    /// Opt-in, direct scalar RODAS5P driver with verification before commit.
    /// Absolute tolerance is enforced everywhere (stronger than atol+rtol*|y|).
    /// The requested relative tolerance remains unchanged in candidate solves.
    /// No exact-solution callback is attached or consulted. This API requires a
    /// positive atol; pure relative tolerances need a separate verified scale.
    pub fn integrate_verified(
        &self,
        span: (f64, f64),
        initial_center: f64,
        initial_radius: f64,
        output_times: &[f64],
        config: &AdaptiveStepConfig,
    ) -> Result<Pr101Run, Pr101Error> {
        config.validate()?;
        if !(0.0 <= span.0
            && span.0 <= span.1
            && span.1 <= 1.0
            && initial_center.is_finite()
            && initial_radius.is_finite()
            && initial_radius >= 0.0
            && config.atol > 0.0
            && initial_radius <= config.atol * 0.5)
        {
            return Err(Pr101Error::Invalid(
                "span, state, radius or positive absolute budget",
            ));
        }
        if output_times
            .iter()
            .any(|&t| !t.is_finite() || t < span.0 || t > span.1)
            || output_times.windows(2).any(|pair| pair[0] >= pair[1])
        {
            return Err(Pr101Error::Invalid(
                "strictly increasing in-span outputs required",
            ));
        }
        let problem = self.candidate_problem()?;
        let linear = LinearSolverConfig {
            method: LinearMethod::Direct,
            ..LinearSolverConfig::default()
        };
        let mut run = Pr101Run {
            segments: Vec::new(),
            outputs: Vec::new(),
            success: false,
            failure: None,
            attempts: 0,
            rejected_attempts: 0,
            solver_work: WorkCounters::default(),
            verification_work: DenseSegmentWork::default(),
        };
        let mut cursor = 0;
        if output_times.first().copied() == Some(span.0) {
            run.outputs.push(Pr101Output {
                time: span.0,
                center: initial_center,
                radius: initial_radius,
            });
            cursor = 1;
        }
        let (mut t, mut state, mut radius) = (span.0, initial_center, initial_radius);
        let mut proposed = config.initial_step.min(config.max_step);
        let tube = config.atol * 0.5;
        while t < span.1 && run.attempts < config.max_attempts {
            let h = match crate::output::end_step_capped(t, proposed, span.1, config.step_cap()) {
                Ok(h) => h,
                Err(error) => {
                    run.failure = Some(error.to_string());
                    break;
                }
            };
            if crate::output::below_min_step(t, h, config.min_step) && t + h < span.1 {
                run.failure = Some("verified driver minimum step reached".into());
                break;
            }
            run.attempts += 1;
            let accepted_before = run.solver_work.accepted_steps;
            let rejected_before = run.solver_work.rejected_steps;
            let candidate = sequential_step(
                &problem,
                t,
                &[state],
                h,
                &linear,
                None,
                config.atol,
                config.rtol,
                true,
                &mut run.solver_work,
            );
            // The outer verified transaction owns the disposition. Candidate
            // step counters may already classify its unverified result; retain
            // every work counter but normalize these two status counters.
            run.solver_work.accepted_steps = accepted_before;
            run.solver_work.rejected_steps = rejected_before;
            let trial =
                (|| -> Result<(Pr101VerifiedSegment, Vec<Pr101Output>, usize), Pr101Error> {
                    let step = candidate?;
                    let curve =
                        Rodas5pQuarticSegment::from_step(&step, &mut run.verification_work)?;
                    // Reserve future global-error headroom. Spending the full
                    // tube early can make an expanding orbit impossible to
                    // resume even after arbitrarily shortening later steps.
                    let progress = ((step.t_new - span.0) / (span.1 - span.0)).clamp(0.0, 1.0);
                    let trial_tube = (initial_radius + (tube - initial_radius) * progress)
                        .max(initial_radius)
                        .min(tube);
                    let verified =
                        self.verify_segment(curve, radius, trial_tube, &mut run.verification_work)?;
                    let mut next = cursor;
                    let mut pending = Vec::new();
                    while next < output_times.len() && output_times[next] <= step.t_new {
                        let output =
                            verified.evaluate(output_times[next], &mut run.verification_work)?;
                        if output.radius > config.atol {
                            return Err(Pr101Error::Tube {
                                radius: output.radius,
                                tube: config.atol,
                            });
                        }
                        pending.push(output);
                        next += 1;
                    }
                    Ok((verified, pending, next))
                })();
            match trial {
                Ok((verified, pending, next)) => {
                    run.solver_work.accepted_steps = accepted_before.saturating_add(1);
                    t = verified.t1;
                    let mut endpoint = [0.0];
                    // This exact endpoint copy has already been validated by
                    // segment construction; it cannot change candidate state.
                    verified.curve.evaluate_center_at_into(
                        t,
                        &mut endpoint,
                        &mut run.verification_work,
                    )?;
                    state = endpoint[0];
                    radius = verified.bound.endpoint_radius;
                    run.outputs.extend(pending);
                    cursor = next;
                    run.segments.push(verified);
                    proposed = (h * 1.5).min(config.max_step);
                }
                Err(error) => {
                    // The stateless candidate has no controller/recycle cache
                    // to roll back. No time, state, radius, output cursor or
                    // accepted segment has been changed before this branch.
                    run.solver_work.rejected_steps = rejected_before.saturating_add(1);
                    run.rejected_attempts += 1;
                    proposed = h * 0.5;
                    run.failure = Some(error.to_string());
                }
            }
        }
        run.success = t == span.1 && cursor == output_times.len();
        if run.success {
            run.failure = None;
        } else if run.failure.is_none() {
            run.failure = Some("verified driver attempt budget exhausted".into());
        }
        Ok(run)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn refused_transport_stops_ledger_before_unexecuted_integral() {
        let mut work = DenseSegmentWork::default();
        // The exponent scale executes, then exp(1000) refuses. None of the
        // signed-integral or final transport primitives may be precharged.
        assert!(signed_transport(1000.0, 1.0, 1.0, 1.0, &mut work).is_err());
        assert_eq!(work.provider_operations, 2);
    }

    #[test]
    fn refused_final_add_keeps_both_attempted_products() {
        let mut work = DenseSegmentWork::default();
        assert!(signed_transport(0.0, 1.0, f64::MAX, f64::MAX, &mut work).is_err());
        assert_eq!(work.provider_operations, 3);
    }

    #[test]
    fn signed_zero_and_expansion_transport_are_finite() {
        let mut work = DenseSegmentWork::default();
        assert_eq!(
            signed_transport(0.0, 0.25, 0.5, 2.0, &mut work).unwrap(),
            1.0
        );
        assert_eq!(work.provider_operations, 3);
        let mut work = DenseSegmentWork::default();
        let value = signed_transport(1.0, 0.25, 0.5, 2.0, &mut work).unwrap();
        assert!(value >= 0.5 * 0.25_f64.exp() + 2.0 * 0.25_f64.exp_m1());
        assert_eq!(work.provider_operations, 8);
    }
}
